PCA.no_escape_no_leak.statement:
Model (state inline):
section PCA
variable {P R : Type}
def canAccess (inScope : P → R → Prop) (isPriv : P → Prop) (isUnowned : R → Prop)
    (c : P) (r : R) : Prop := inScope c r ∨ isPriv c ∨ isUnowned r

Theorem: With no privileged and no unowned escape, any granted access is in-scope: ∀ inScope c r, (∀ c, ¬isPriv c) → (∀ r, ¬isUnowned r) → canAccess inScope isPriv isUnowned c r → inScope c r.

